package main

import (
	"crypto/rsa"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"
)

// TokenBucket represents a local thread-safe rate limiter
type TokenBucket struct {
	mu           sync.Mutex
	tokens       float64
	capacity     float64
	refillRate   float64 // tokens per second
	lastRefilled time.Time
}

func NewTokenBucket(capacity, refillRate float64) *TokenBucket {
	return &TokenBucket{
		tokens:       capacity,
		capacity:     capacity,
		refillRate:   refillRate,
		lastRefilled: time.Now(),
	}
}

func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.lastRefilled).Seconds()
	tb.lastRefilled = now

	tb.tokens = tb.tokens + elapsed*tb.refillRate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= 1.0 {
		tb.tokens -= 1.0
		return true
	}
	return false
}

// Router configures path-based proxy rules
type GatewayRoute struct {
	PathPrefix string
	TargetURL  *url.URL
	Proxy      *httputil.ReverseProxy
}

type Gateway struct {
	routes      []GatewayRoute
	rateLimiter *TokenBucket
	publicKey   *rsa.PublicKey // Asymmetric public key for RS256 JWT validation
}

type Claims struct {
	UserID string `json:"sub"`
	Exp    int64  `json:"exp"`
}

// VerifyJWT extracts user ID from a mock RS256 token signature
func (gw *Gateway) VerifyJWT(authHeader string) (string, error) {
	if !strings.HasPrefix(authHeader, "Bearer ") {
		return "", errors.New("missing or invalid authorization header")
	}
	tokenString := strings.TrimPrefix(authHeader, "Bearer ")
	parts := strings.Split(tokenString, ".")
	if len(parts) != 3 {
		return "", errors.New("invalid token format")
	}

	payloadBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return "", err
	}

	var claims Claims
	if err := json.Unmarshal(payloadBytes, &claims); err != nil {
		return "", err
	}

	if time.Now().Unix() > claims.Exp {
		return "", errors.New("token has expired")
	}

	return claims.UserID, nil
}

func (gw *Gateway) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// 1. Rate Limiting Check
	if !gw.rateLimiter.Allow() {
		w.Header().Set("Retry-After", "5")
		http.Error(w, "Rate limit exceeded. Please try again later.", http.StatusTooManyRequests)
		return
	}

	// 2. Client Authentication Validation
	userID, err := gw.VerifyJWT(r.Header.Get("Authorization"))
	if err != nil {
		http.Error(w, fmt.Sprintf("Unauthorized: %v", err), http.StatusUnauthorized)
		return
	}

	// 3. Dynamic Route Matching & Reverse Proxying
	for _, route := range gw.routes {
		if strings.HasPrefix(r.URL.Path, route.PathPrefix) {
			// Inject identified metadata for downstream microservices
			r.Header.Set("X-User-Id", userID)

			// Dynamic Path rewrite if necessary (e.g. stripping prefix)
			r.URL.Path = strings.TrimPrefix(r.URL.Path, route.PathPrefix)
			if !strings.HasPrefix(r.URL.Path, "/") {
				r.URL.Path = "/" + r.URL.Path
			}

			// Forward request to internal target
			route.Proxy.ServeHTTP(w, r)
			return
		}
	}

	http.Error(w, "Route not found", http.StatusNotFound)
}

func main() {
	userURL, _ := url.Parse("http://localhost:8081")
	orderURL, _ := url.Parse("http://localhost:8082")

	userProxy := httputil.NewSingleHostReverseProxy(userURL)
	orderProxy := httputil.NewSingleHostReverseProxy(orderURL)

	gateway := &Gateway{
		rateLimiter: NewTokenBucket(100.0, 10.0), // Cap 100 requests, refills 10/sec
		routes: []GatewayRoute{
			{PathPrefix: "/api/v1/users", TargetURL: userURL, Proxy: userProxy},
			{PathPrefix: "/api/v1/orders", TargetURL: orderURL, Proxy: orderProxy},
		},
	}

	log.Printf("Starting Micro-API Gateway on :8000...")
	log.Fatal(http.ListenAndServe(":8000", gateway))
}

package main

import (
    "crypto"
    "crypto/rsa"
    "crypto/sha256"
    "encoding/base64"
    "encoding/json"
    "errors"
    "fmt"
    "math/big"
    "strings"
    "time"
)

type JWK struct {
    Kty string `json:"kty"`
    Kid string `json:"kid"`
    N   string `json:"n"`
    E   string `json:"e"`
}

type JWKS struct {
    Keys []JWK `json:"keys"`
}

type JWTHeader struct {
    Alg string `json:"alg"`
    Kid string `json:"kid"`
    Typ string `json:"typ"`
}

type JWTClaims struct {
    Sub string `json:"sub"`
    Iss string `json:"iss"`
    Aud string `json:"aud"`
    Exp int64  `json:"exp"`
}

func base64URLDecode(s string) ([]byte, error) {
    if l := len(s) % 4; l > 0 {
        s += strings.Repeat("=", 4-l)
    }
    return base64.URLEncoding.DecodeString(s)
}

func parseRSAPublicKey(nStr, eStr string) (*rsa.PublicKey, error) {
    nBytes, err := base64URLDecode(nStr)
    if err != nil {
        return nil, err
    }
    eBytes, err := base64URLDecode(eStr)
    if err != nil {
        return nil, err
    }
    if len(eBytes) < 4 {
        padded := make([]byte, 4)
        copy(padded[4-len(eBytes):], eBytes)
        eBytes = padded
    }
    var eVal uint32
    eVal = uint32(eBytes[0])<<24 | uint32(eBytes[1])<<16 | uint32(eBytes[2])<<8 | uint32(eBytes[3])
    return &rsa.PublicKey{
        N: new(big.Int).SetBytes(nBytes),
        E: int(eVal),
    }, nil
}

func VerifyRS256Token(tokenString string, jwksJSON string, expectedIss, expectedAud string) (*JWTClaims, error) {
    parts := strings.Split(tokenString, ".")
    if len(parts) != 3 {
        return nil, errors.New("invalid token format")
    }
    headerSegment, payloadSegment, signatureSegment := parts[0], parts[1], parts[2]

    headerBytes, err := base64URLDecode(headerSegment)
    if err != nil {
        return nil, fmt.Errorf("failed to decode header: %w", err)
    }
    var header JWTHeader
    if err := json.Unmarshal(headerBytes, &header); err != nil {
        return nil, err
    }
    if header.Alg != "RS256" {
        return nil, fmt.Errorf("unsupported algorithm: %s", header.Alg)
    }

    payloadBytes, err := base64URLDecode(payloadSegment)
    if err != nil {
        return nil, fmt.Errorf("failed to decode payload: %w", err)
    }
    var claims JWTClaims
    if err := json.Unmarshal(payloadBytes, &claims); err != nil {
        return nil, err
    }

    var jwks JWKS
    if err := json.Unmarshal([]byte(jwksJSON), &jwks); err != nil {
        return nil, fmt.Errorf("failed to parse JWKS: %w", err)
    }
    var targetKey *JWK
    for _, key := range jwks.Keys {
        if key.Kid == header.Kid {
            targetKey = &key
            break
        }
    }
    if targetKey == nil {
        return nil, fmt.Errorf("key id %s not found in JWKS", header.Kid)
    }

    pubKey, err := parseRSAPublicKey(targetKey.N, targetKey.E)
    if err != nil {
        return nil, fmt.Errorf("failed to parse public key: %w", err)
    }

    signingInput := headerSegment + "." + payloadSegment
    signatureBytes, err := base64URLDecode(signatureSegment)
    if err != nil {
        return nil, fmt.Errorf("failed to decode signature: %w", err)
    }

    hasher := sha256.New()
    hasher.Write([]byte(signingInput))
    hashed := hasher.Sum(nil)

    err = rsa.VerifyPKCS1v15(pubKey, crypto.SHA256, hashed, signatureBytes)
    if err != nil {
        return nil, fmt.Errorf("invalid signature: %w", err)
    }

    if time.Now().Unix() > claims.Exp {
        return nil, errors.New("token has expired")
    }
    if claims.Iss != expectedIss {
        return nil, fmt.Errorf("invalid issuer: got %s, expected %s", claims.Iss, expectedIss)
    }
    if claims.Aud != expectedAud {
        return nil, fmt.Errorf("invalid audience: got %s, expected %s", claims.Aud, expectedAud)
    }

    return &claims, nil
}

package main

import (
	"fmt"
	"sort"
)

// MaxKeys defines the order (M) of our B+ Tree node capacity.
// A node splits when it exceeds this threshold.
const MaxKeys = 3

// Node represents a generic B+ Tree node.
type Node interface {
	isLeaf() bool
}

// InternalNode routes queries down the tree but stores no raw data.
type InternalNode struct {
	keys     []int
	children []Node
}

func (n *InternalNode) isLeaf() bool { return false }

// LeafNode stores key-value pairs and links horizontally to its siblings.
type LeafNode struct {
	keys []int
	vals []string
	next *LeafNode
	prev *LeafNode
}

func (n *LeafNode) isLeaf() bool { return true }

// BPlusTree coordinates operations and tracks the root node.
type BPlusTree struct {
	root Node
}

// NewBPlusTree creates an empty tree initialized with a leaf root.
func NewBPlusTree() *BPlusTree {
	return &BPlusTree{
		root: &LeafNode{
			keys: make([]int, 0),
			vals: make([]string, 0),
		},
	}
}

// Search traverses the tree to retrieve a key's associated value.
func (t *BPlusTree) Search(key int) (string, bool) {
	curr := t.root
	for !curr.isLeaf() {
		internal := curr.(*InternalNode)
		idx := sort.Search(len(internal.keys), func(i int) bool {
			return internal.keys[i] > key
		})
		curr = internal.children[idx]
	}
	leaf := curr.(*LeafNode)
	idx := sort.SearchInts(leaf.keys, key)
	if idx < len(leaf.keys) && leaf.keys[idx] == key {
		return leaf.vals[idx], true
	}
	return "", false
}

// Insert adds a key-value record to the tree, triggering node splits as needed.
func (t *BPlusTree) Insert(key int, val string) {
	newKey, newChild, split := t.insert(t.root, key, val)
	if split {
		// Root split requires establishing a new parent internal node.
		t.root = &InternalNode{
			keys:     []int{newKey},
			children: []Node{t.root, newChild},
		}
	}
}

func (t *BPlusTree) insert(node Node, key int, val string) (int, Node, bool) {
	if node.isLeaf() {
		leaf := node.(*LeafNode)
		idx := sort.SearchInts(leaf.keys, key)

		// If key exists, overwrite the value
		if idx < len(leaf.keys) && leaf.keys[idx] == key {
			leaf.vals[idx] = val
			return 0, nil, false
		}

		// Insert key-value pair in sorted position
		leaf.keys = append(leaf.keys, 0)
		leaf.vals = append(leaf.vals, "")
		copy(leaf.keys[idx+1:], leaf.keys[idx:])
		copy(leaf.vals[idx+1:], leaf.vals[idx:])
		leaf.keys[idx] = key
		leaf.vals[idx] = val

		if len(leaf.keys) > MaxKeys {
			return t.splitLeaf(leaf)
		}
		return 0, nil, false
	}

	internal := node.(*InternalNode)
	idx := sort.Search(len(internal.keys), func(i int) bool {
		return internal.keys[i] > key
	})

	splitKey, childNode, split := t.insert(internal.children[idx], key, val)
	if split {
		// Insert split key and reference child in internal node
		internal.keys = append(internal.keys, 0)
		internal.children = append(internal.children, nil)
		copy(internal.keys[idx+1:], internal.keys[idx:])
		copy(internal.children[idx+2:], internal.children[idx+1:])
		internal.keys[idx] = splitKey
		internal.children[idx+1] = childNode

		if len(internal.keys) > MaxKeys {
			return t.splitInternal(internal)
		}
	}
	return 0, nil, false
}

// splitLeaf divides a LeafNode when capacity limit is breached.
func (t *BPlusTree) splitLeaf(leaf *LeafNode) (int, Node, bool) {
	mid := len(leaf.keys) / 2
	sibling := &LeafNode{
		keys: append([]int(nil), leaf.keys[mid:]...),
		vals: append([]string(nil), leaf.vals[mid:]...),
		next: leaf.next,
		prev: leaf,
	}
	if leaf.next != nil {
		leaf.next.prev = sibling
	}
	leaf.next = sibling
	leaf.keys = leaf.keys[:mid]
	leaf.vals = leaf.vals[:mid]

	// Bubble up the smallest key in the right sibling leaf node
	return sibling.keys[0], sibling, true
}

// splitInternal divides an InternalNode when keys exceed thresholds.
func (t *BPlusTree) splitInternal(internal *InternalNode) (int, Node, bool) {
	mid := len(internal.keys) / 2
	promoteKey := internal.keys[mid]

	sibling := &InternalNode{
		keys:     append([]int(nil), internal.keys[mid+1:]...),
		children: append([]Node(nil), internal.children[mid+1:]...),
	}

	internal.keys = internal.keys[:mid]
	internal.children = internal.children[:mid+1]

	return promoteKey, sibling, true
}

func main() {
	tree := NewBPlusTree()
	keys := []int{10, 20, 5, 15, 30, 25}
	for _, k := range keys {
		tree.Insert(k, fmt.Sprintf("val-%d", k))
	}

	for _, k := range keys {
		val, found := tree.Search(k)
		fmt.Printf("Key: %d, Val: %s, Found: %t\n", k, val, found)
	}
}

package main

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// HeaderSize is the size of the record header:
// Timestamp (8 bytes) + KeySize (4 bytes) + ValueSize (4 bytes)
const HeaderSize = 16

// KeydirEntry stores the location parameters of a key in the log files.
type KeydirEntry struct {
	FileID    string
	ValueSize int32
	Offset    int64
	Timestamp int64
}

// Bitcask represents a thread-safe log-structured storage engine.
type Bitcask struct {
	mu         sync.RWMutex
	dirPath    string
	activeFile *os.File
	activeID   string
	keydir     map[string]KeydirEntry
}

// NewBitcask opens or initializes a Bitcask storage directory.
func NewBitcask(dirPath string) (*Bitcask, error) {
	if err := os.MkdirAll(dirPath, 0755); err != nil {
		return nil, err
	}

	bc := &Bitcask{
		dirPath: dirPath,
		keydir:  make(map[string]KeydirEntry),
	}

	if err := bc.recoverKeydir(); err != nil {
		return nil, err
	}

	if err := bc.openNewActiveFile(); err != nil {
		return nil, err
	}

	return bc, nil
}

// Put appends a key-value record to the active log file and updates Keydir.
func (bc *Bitcask) Put(key string, val string) error {
	bc.mu.Lock()
	defer bc.mu.Unlock()

	keyBytes := []byte(key)
	valBytes := []byte(val)
	timestamp := time.Now().UnixNano()
	keySize := int32(len(keyBytes))
	valSize := int32(len(valBytes))

	// Write record to active file
	offset, err := bc.activeFile.Seek(0, io.SeekEnd)
	if err != nil {
		return err
	}

	headerBuf := new(bytes.Buffer)
	binary.Write(headerBuf, binary.BigEndian, timestamp)
	binary.Write(headerBuf, binary.BigEndian, keySize)
	binary.Write(headerBuf, binary.BigEndian, valSize)

	if _, err := bc.activeFile.Write(headerBuf.Bytes()); err != nil {
		return err
	}
	if _, err := bc.activeFile.Write(keyBytes); err != nil {
		return err
	}
	if _, err := bc.activeFile.Write(valBytes); err != nil {
		return err
	}

	// Update memory-based Keydir lookup map
	bc.keydir[key] = KeydirEntry{
		FileID:    bc.activeID,
		ValueSize: valSize,
		Offset:    offset,
		Timestamp: timestamp,
	}

	return nil
}

// Get retrieves a key's value in a single disk seek using the Keydir entry.
func (bc *Bitcask) Get(key string) (string, error) {
	bc.mu.RLock()
	entry, exists := bc.keydir[key]
	bc.mu.RUnlock()

	if !exists {
		return "", fmt.Errorf("key not found")
	}

	filePath := filepath.Join(bc.dirPath, entry.FileID+".log")
	file, err := os.Open(filePath)
	if err != nil {
		return "", err
	}
	defer file.Close()

	// Skip timestamp + keysize metadata to read value
	// LSN offset + HeaderSize matches the location of the key bytes
	// LSN offset + HeaderSize + KeySize matches the location of the value bytes
	// We calculate key size to jump directly to value bytes
	keySizeVal := entry.Offset // Temporary store helper to read the key size

	var ts int64
	var ks, vs int32
	headerBytes := make([]byte, HeaderSize)
	if _, err := file.ReadAt(headerBytes, entry.Offset); err != nil {
		return "", err
	}
	buf := bytes.NewReader(headerBytes)
	binary.Read(buf, binary.BigEndian, &ts)
	binary.Read(buf, binary.BigEndian, &ks)
	binary.Read(buf, binary.BigEndian, &vs)

	valOffset := entry.Offset + HeaderSize + int64(ks)
	valBytes := make([]byte, entry.ValueSize)
	if _, err := file.ReadAt(valBytes, valOffset); err != nil {
		return "", err
	}

	return string(valBytes), nil
}

func (bc *Bitcask) openNewActiveFile() error {
	if bc.activeFile != nil {
		bc.activeFile.Close()
	}
	bc.activeID = fmt.Sprintf("data-%d", time.Now().UnixNano())
	filePath := filepath.Join(bc.dirPath, bc.activeID+".log")
	file, err := os.OpenFile(filePath, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0644)
	if err != nil {
		return err
	}
	bc.activeFile = file
	return nil
}

// recoverKeydir scans log files on startup to rebuild the in-memory lookup map.
func (bc *Bitcask) recoverKeydir() error {
	files, err := filepath.Glob(filepath.Join(bc.dirPath, "*.log"))
	if err != nil {
		return err
	}

	for _, path := range files {
		fileID := filepath.Base(path[:len(path)-4])
		file, err := os.Open(path)
		if err != nil {
			return err
		}

		var offset int64 = 0
		for {
			header := make([]byte, HeaderSize)
			_, err := file.ReadAt(header, offset)
			if err == io.EOF {
				break
			}
			if err != nil {
				break
			}

			var ts int64
			var ks, vs int32
			buf := bytes.NewReader(header)
			binary.Read(buf, binary.BigEndian, &ts)
			binary.Read(buf, binary.BigEndian, &ks)
			binary.Read(buf, binary.BigEndian, &vs)

			keyBytes := make([]byte, ks)
			if _, err := file.ReadAt(keyBytes, offset+HeaderSize); err != nil {
				break
			}

			key := string(keyBytes)
			bc.keydir[key] = KeydirEntry{
				FileID:    fileID,
				ValueSize: vs,
				Offset:    offset,
				Timestamp: ts,
			}

			offset += HeaderSize + int64(ks) + int64(vs)
		}
		file.Close()
	}
	return nil
}

// Close terminates the active file handle.
func (bc *Bitcask) Close() {
	bc.mu.Lock()
	defer bc.mu.Unlock()
	if bc.activeFile != nil {
		bc.activeFile.Close()
	}
}

func main() {
	dir := "./bitcask_temp_db"
	defer os.RemoveAll(dir)

	bc, err := NewBitcask(dir)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	defer bc.Close()

	bc.Put("user_id_101", "Alice")
	bc.Put("user_id_102", "Bob")
	bc.Put("user_id_101", "Alice Cooper") // Overwrite value

	val, err := bc.Get("user_id_101")
	fmt.Printf("Retrieved user_id_101: %s (Err: %v)\n", val, err)

	val2, err := bc.Get("user_id_102")
	fmt.Printf("Retrieved user_id_102: %s (Err: %v)\n", val2, err)
}

package main

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

// SingleFlight collapses concurrent requests for the same key.
type SingleFlight struct {
    mu sync.Mutex
    m  map[string]*call
}

type call struct {
    wg  sync.WaitGroup
    val interface{}
    err error
}

func (sf *SingleFlight) Do(key string, fn func() (interface{}, error)) (interface{}, error) {
    sf.mu.Lock()
    if sf.m == nil {
        sf.m = make(map[string]*call)
    }
    if c, ok := sf.m[key]; ok {
        sf.mu.Unlock()
        c.wg.Wait()
        return c.val, c.err
    }
    c := new(call)
    c.wg.Add(1)
    sf.m[key] = c
    sf.mu.Unlock()

    c.val, c.err = fn()
    c.wg.Done()

    sf.mu.Lock()
    delete(sf.m, key)
    sf.mu.Unlock()

    return c.val, c.err
}

// LeaseCache handles lease-based cache writes to prevent race conditions.
type LeaseCache struct {
    mu      sync.Mutex
    data    map[string]cacheItem
    leases  map[string]uint64
    tokenID uint64
}

type cacheItem struct {
    value      string
    expiration time.Time
}

func NewLeaseCache() *LeaseCache {
    return &LeaseCache{
        data:   make(map[string]cacheItem),
        leases: make(map[string]uint64),
    }
}

func (lc *LeaseCache) Get(key string) (string, uint64, bool) {
    lc.mu.Lock()
    defer lc.mu.Unlock()

    item, ok := lc.data[key]
    if ok && time.Now().Before(item.expiration) {
        return item.value, 0, true
    }

    // Generate a lease token for the caller on a cache miss
    token := atomic.AddUint64(&lc.tokenID, 1)
    lc.leases[key] = token
    return "", token, false
}

func (lc *LeaseCache) Set(key string, value string, token uint64, ttl time.Duration) bool {
    lc.mu.Lock()
    defer lc.mu.Unlock()

    activeToken, hasLease := lc.leases[key]
    if !hasLease || activeToken != token {
        // The lease token is stale or invalid; reject the cache update
        return false
    }

    lc.data[key] = cacheItem{
        value:      value,
        expiration: time.Now().Add(ttl),
    }
    delete(lc.leases, key)
    return true
}

func (lc *LeaseCache) Invalidate(key string) {
    lc.mu.Lock()
    defer lc.mu.Unlock()
    delete(lc.data, key)
    delete(lc.leases, key)
}

async function getUser(id: string): Promise<User> {
  // 1. Check cache
  const cached = await redis.get(`user:${id}`);
  if (cached) return JSON.parse(cached);

  // 2. Cache miss - fetch from DB
  const user = await db.users.findUnique({ where: { id } });
  if (!user) throw new NotFoundError();

  // 3. Populate cache with TTL
  await redis.setex(`user:${id}`, 3600, JSON.stringify(user));
  return user;
}

// Invalidate on write
async function updateUser(id: string, data: Partial<User>) {
  await db.users.update({ where: { id }, data });
  await redis.del(`user:${id}`);  // bust cache
}

func GetUser(ctx context.Context, id string) (*User, error) {
    // Check cache
    cached, err := rdb.Get(ctx, "user:"+id).Result()
    if err == nil {
        var u User
        json.Unmarshal([]byte(cached), &u)
        return &u, nil
    }

    // Cache miss
    u, err := db.QueryUser(ctx, id)
    if err != nil {
        return nil, err
    }

    // Populate cache (1 hour TTL)
    data, _ := json.Marshal(u)
    rdb.Set(ctx, "user:"+id, data, time.Hour)
    return u, nil
}

import redis
import json
from functools import wraps

r = redis.Redis()

def cached(ttl=3600):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = f"{fn.__name__}:{args}:{kwargs}"
            hit = r.get(key)
            if hit:
                return json.loads(hit)
            result = fn(*args, **kwargs)
            r.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator

@cached(ttl=1800)
def get_user(user_id):
    return db.query("SELECT * FROM users WHERE id=%s", user_id)

interface Env {
  ORIGIN_URL: string;
}

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext
  ): Promise<Response> {
    const url = new URL(request.url);

    // Only cache GET and HEAD requests
    if (request.method !== "GET" && request.method !== "HEAD") {
      return fetch(`${env.ORIGIN_URL}${url.pathname}${url.search}`, request);
    }

    const cache = caches.default;
    // Look up request in the local edge cache
    let response = await cache.match(request);

    if (!response) {
      // Cache miss: forward request to the origin server
      const originUrl = `${env.ORIGIN_URL}${url.pathname}${url.search}`;
      const originResponse = await fetch(originUrl, {
        headers: request.headers,
      });

      // Clone the response to modify headers and write to cache
      const newHeaders = new Headers(originResponse.headers);

      // Configure cache lifetime (s-maxage) and background refresh window
      newHeaders.set(
        "Cache-Control",
        "public, s-maxage=3600, stale-while-revalidate=60"
      );

      // Establish tag-based invalidation via Surrogate-Keys
      const tags = originResponse.headers.get("X-Cache-Tags") || "all-assets";
      newHeaders.set("Surrogate-Key", tags);

      response = new Response(originResponse.body, {
        status: originResponse.status,
        statusText: originResponse.statusText,
        headers: newHeaders,
      });

      // Cache response asynchronously to avoid blocking the client response
      ctx.waitUntil(cache.put(request, response.clone()));
    }

    return response;
  },
};

-- PHASE 1: EXPAND (Deploy new schema alongside old code)
-- Add a new column to store updated structures, leaving the old untouched
ALTER TABLE users ADD COLUMN phone_number_v2 VARCHAR(20) DEFAULT NULL;

-- Sync writes from both old and new code using a trigger
CREATE OR REPLACE FUNCTION sync_phone_numbers()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.phone_number IS NOT NULL AND NEW.phone_number_v2 IS NULL THEN
    NEW.phone_number_v2 := NEW.phone_number;
  ELSIF NEW.phone_number_v2 IS NOT NULL AND NEW.phone_number IS NULL THEN
    NEW.phone_number := NEW.phone_number_v2;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_phone
BEFORE INSERT OR UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION sync_phone_numbers();

-- PHASE 2: MIGRATE (Data backfill in the background)
-- Run in small batches to prevent database locking
-- UPDATE users SET phone_number_v2 = phone_number 
-- WHERE phone_number_v2 IS NULL AND phone_number IS NOT NULL;

-- PHASE 3: CONTRACT (Clean up old schema elements after full deployment)
DROP TRIGGER IF EXISTS trg_sync_phone ON users;
DROP FUNCTION IF EXISTS sync_phone_numbers;
ALTER TABLE users DROP COLUMN phone_number;
ALTER TABLE users RENAME COLUMN phone_number_v2 TO phone_number;

