You can prevent false sharing by ensuring that independent variables accessed by different threads are allocated on separate cache lines.

In C++11 and later, you can use the `alignas` specifier to align variables to cache line boundaries:

```cpp
struct OptimizedData {
    alignas(64) uint64_t thread1_count;
    alignas(64) uint64_t thread2_count;
};
```

This instructs the compiler to insert padding bytes so that each variable starts on a new 64-byte boundary, isolating them on separate cache lines. While this uses slightly more memory, it eliminates false sharing and prevents invalidation loops.

---

codeExamples.code:
#include <iostream>
#include <thread>
#include <vector>
#include <chrono>
#include <new>

const uint64_t ITERATIONS = 100000000ULL;

// Structure demonstrating False Sharing
// Adjacent members share the same 64-byte cache line
struct NaiveData {
    uint64_t thread1_count;
    uint64_t thread2_count;
} naive_data;

// Structure utilizing alignment attributes to isolate members on separate cache lines
struct OptimizedData {
    alignas(64) uint64_t thread1_count;
    alignas(64) uint64_t thread2_count;
} optimized_data;

void run_naive_worker1() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        naive_data.thread1_count++;
    }
}

void run_naive_worker2() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        naive_data.thread2_count++;
    }
}

void run_optimized_worker1() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        optimized_data.thread1_count++;
    }
}

void run_optimized_worker2() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        optimized_data.thread2_count++;
    }
}

int main() {
    std::cout << "Cache line size suggestion: " << std::hardware_destructive_interference_size << " bytes\n";
    std::cout << "Size of NaiveData: " << sizeof(NaiveData) << " bytes\n";
    std::cout << "Size of OptimizedData: " << sizeof(OptimizedData) << " bytes\n\n";

    // Test Naive execution (False Sharing)
    auto start_naive = std::chrono::high_resolution_clock::now();
    std::thread t1(run_naive_worker1);
    std::thread t2(run_naive_worker2);
    t1.join();
    t2.join();
    auto end_naive = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> naive_duration = end_naive - start_naive;
    std::cout << "Naive execution time: " << naive_duration.count() << " ms\n";

    // Test Optimized execution (Aligned data boundaries)
    auto start_opt = std::chrono::high_resolution_clock::now();
    std::thread t3(run_optimized_worker1);
    std::thread t4(run_optimized_worker2);
    t3.join();
    t4.join();
    auto end_opt = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> opt_duration = end_opt - start_opt;
    std::cout << "Optimized execution time: " << opt_duration.count() << " ms\n";

    double speedup = naive_duration.count() / opt_duration.count();
    std::cout << "Speedup achieved: " << speedup << "x\n";

    return 0;
}

package main

import (
    "fmt"
    "sync"
    "time"
)

type WritePayload struct {
    Key   string
    Value string
}

type Hint struct {
    TargetNode string
    Payload    WritePayload
    Timestamp  time.Time
}

type Node struct {
    Name      string
    Reachable bool
    Data      map[string]string
    mu        sync.Mutex
}

func (n *Node) Write(key, val string) bool {
    n.mu.Lock()
    defer n.mu.Unlock()
    if !n.Reachable {
        return false
    }
    n.Data[key] = val
    return true
}

type Cluster struct {
    Nodes       []*Node
    N           int
    W           int
    R           int
    HintStorage map[string][]Hint
    mu          sync.Mutex
}

func NewCluster(nodeNames []string, w, r int) *Cluster {
    nodes := make([]*Node, len(nodeNames))
    for i, name := range nodeNames {
        nodes[i] = &Node{
            Name:      name,
            Reachable: true,
            Data:      make(map[string]string),
        }
    }
    return &Cluster{
        Nodes:       nodes,
        N:           len(nodeNames),
        W:           w,
        R:           r,
        HintStorage: make(map[string][]Hint),
    }
}

func (c *Cluster) Write(key, val string) error {
    payload := WritePayload{Key: key, Value: val}
    var wg sync.WaitGroup
    confirmations := 0
    var confMu sync.Mutex

    for _, node := range c.Nodes {
        wg.Add(1)
        go func(n *Node) {
            defer wg.Done()
            if success := n.Write(key, val); success {
                confMu.Lock()
                confirmations++
                confMu.Unlock()
            }
        }(node)
    }
    wg.Wait()

    if confirmations >= c.W {
        fmt.Printf("Strict write quorum met: %d/%d confirmations\n", confirmations, c.W)
        return nil
    }

    fmt.Printf("Strict write quorum failed (%d/%d). Attempting Sloppy Quorum...\n", confirmations, c.W)

    activeWrites := confirmations
    for _, node := range c.Nodes {
        if activeWrites >= c.W {
            break
        }

        node.mu.Lock()
        isReachable := node.Reachable
        node.mu.Unlock()

        if !isReachable {
            for _, backupNode := range c.Nodes {
                if backupNode.Name == node.Name {
                    continue
                }
                backupNode.mu.Lock()
                backupReachable := backupNode.Reachable
                backupNode.mu.Unlock()

                if backupReachable {
                    c.mu.Lock()
                    c.HintStorage[backupNode.Name] = append(c.HintStorage[backupNode.Name], Hint{
                        TargetNode: node.Name,
                        Payload:    payload,
                        Timestamp:  time.Now(),
                    })
                    c.mu.Unlock()

                    fmt.Printf("Stored hint on backup node %s for target offline node %s\n", backupNode.Name, node.Name)
                    activeWrites++
                    break
                }
            }
        }
    }

    if activeWrites >= c.W {
        fmt.Printf("Sloppy write quorum met: %d/%d confirmations (including hints)\n", activeWrites, c.W)
        return nil
    }

    return fmt.Errorf("write failed: failed to satisfy sloppy quorum (%d/%d)", activeWrites, c.W)
}

func (c *Cluster) RecoverNode(nodeName string) {
    var targetNode *Node
    for _, node := range c.Nodes {
        if node.Name == nodeName {
            targetNode = node
            break
        }
    }
    if targetNode == nil {
        return
    }

    targetNode.mu.Lock()
    targetNode.Reachable = true
    targetNode.mu.Unlock()
    fmt.Printf("Node %s has recovered and is online\n", nodeName)

    c.mu.Lock()
    defer c.mu.Unlock()

    for backupName, hints := range c.HintStorage {
        var activeHints []Hint
        for _, hint := range hints {
            if hint.TargetNode == nodeName {
                success := targetNode.Write(hint.Payload.Key, hint.Payload.Value)
                if success {
                    fmt.Printf("Replayed hint from %s to %s for key: %s\n", backupName, nodeName, hint.Payload.Key)
                } else {
                    activeHints = append(activeHints, hint)
                }
            } else {
                activeHints = append(activeHints, hint)
            }
        }
        c.HintStorage[backupName] = activeHints
    }
}

package main

import (
    "context"
    "fmt"
    "sync"
)

type Row struct {
    ID    int
    Value string
    Age   int
}

type ShardConnection interface {
    Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error)
    Exec(ctx context.Context, sql string, args ...interface{}) error
}

type MockShard struct {
    ID   int
    Data []Row
}

func (m *MockShard) Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error) {
    var minAge, maxAge int
    fmt.Sscanf(sql, "SELECT * FROM users WHERE age BETWEEN %d AND %d", &minAge, &maxAge)

    var res []Row
    for _, row := range m.Data {
        if row.Age >= minAge && row.Age <= maxAge {
            res = append(res, row)
        }
    }
    return res, nil
}

func (m *MockShard) Exec(ctx context.Context, sql string, args ...interface{}) error {
    row := args[0].(Row)
    m.Data = append(m.Data, row)
    return nil
}

type Router struct {
    mu          sync.RWMutex
    Shards      map[int]ShardConnection
    IsMigrating bool
    NewShards   map[int]ShardConnection
}

func (r *Router) ResolveShardsForRange(minAge, maxAge int) []int {
    var shardIDs []int
    if minAge <= 30 {
        shardIDs = append(shardIDs, 0)
    }
    if minAge <= 60 && maxAge >= 31 {
        shardIDs = append(shardIDs, 1)
    }
    if maxAge >= 61 {
        shardIDs = append(shardIDs, 2)
    }
    return shardIDs
}

func (r *Router) ScatterGatherQuery(ctx context.Context, minAge, maxAge int) ([]Row, error) {
    shardIDs := r.ResolveShardsForRange(minAge, maxAge)

    r.mu.RLock()
    defer r.mu.RUnlock()

    var wg sync.WaitGroup
    resultChan := make(chan []Row, len(shardIDs))
    errChan := make(chan error, len(shardIDs))

    sql := fmt.Sprintf("SELECT * FROM users WHERE age BETWEEN %d AND %d", minAge, maxAge)

    for _, shardID := range shardIDs {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            shard, exists := r.Shards[id]
            if !exists {
                errChan <- fmt.Errorf("shard %d not configured", id)
                return
            }
            rows, err := shard.Query(ctx, sql)
            if err != nil {
                errChan <- err
                return
            }
            resultChan <- rows
        }(shardID)
    }

    wg.Wait()
    close(resultChan)
    close(errChan)

    if len(errChan) > 0 {
        return nil, <-errChan
    }

    var allRows []Row
    for rows := range resultChan {
        allRows = append(allRows, rows...)
    }

    return allRows, nil
}

func (r *Router) Write(ctx context.Context, shardKey int, row Row) error {
    r.mu.RLock()
    defer r.mu.RUnlock()

    shardID := shardKey % len(r.Shards)
    shard, exists := r.Shards[shardID]
    if !exists {
        return fmt.Errorf("target shard %d not found", shardID)
    }

    err := shard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
    if err != nil {
        return err
    }

    if r.IsMigrating {
        newShardID := shardKey % len(r.NewShards)
        if newShard, exists := r.NewShards[newShardID]; exists {
            go func() {
                _ = newShard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
            }()
        }
    }

    return nil
}

