import (
    "encoding/json"
    "fmt"
    "time"
)

type Resource struct {
    Name     string `json:"name"`
    Replicas int    `json:"replicas"`
    Image    string `json:"image"`
}

// MockGitRepository simulates a remote Git store holding desired state
func FetchDesiredStateFromGit() ([]byte, error) {
    desired := []Resource{
        {Name: "web-server", Replicas: 3, Image: "nginx:1.25"},
        {Name: "db-proxy", Replicas: 2, Image: "envoy:1.28"},
    }
    return json.Marshal(desired)
}

// MockK8sCluster simulates the live Kubernetes cluster state
type MockK8sCluster struct {
    LiveState map[string]*Resource
}

func (c *MockK8sCluster) FetchLiveState() map[string]*Resource {
    return c.LiveState
}

func (c *MockK8sCluster) ApplyChange(r Resource) {
    fmt.Printf("[K8s Cluster] Appying resource update: %s (Replicas: %d, Image: %s)\n", r.Name, r.Replicas, r.Image)
    c.LiveState[r.Name] = &r
}

func (c *MockK8sCluster) DeleteResource(name string) {
    fmt.Printf("[K8s Cluster] Deleting resource: %s\n", name)
    delete(c.LiveState, name)
}

// Reconcile compares desired Git state against live cluster resources
func Reconcile(cluster *MockK8sCluster) {
    desiredBytes, _ := FetchDesiredStateFromGit()
    var desiredState []Resource
    json.Unmarshal(desiredBytes, &desiredState)

    liveState := cluster.FetchLiveState()
    desiredMap := make(map[string]*Resource)

    // 1. Identify updates or missing resources
    for _, res := range desiredState {
        desiredMap[res.Name] = &res
        live, exists := liveState[res.Name]
        if !exists {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Missing resource %s\n", res.Name)
            cluster.ApplyChange(res)
        } else if live.Replicas != res.Replicas || live.Image != res.Image {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Resource %s mismatch. Live: {Replicas: %d, Image: %s}, Desired: {Replicas: %d, Image: %s}\n", 
                res.Name, live.Replicas, live.Image, res.Replicas, res.Image)
            cluster.ApplyChange(res)
        }
    }

    // 2. Identify orphaned resources (present in live cluster but deleted from Git)
    for name := range liveState {
        if _, exists := desiredMap[name]; !exists {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Orphaned resource %s found in cluster but missing from Git\n", name)
            cluster.DeleteResource(name)
        }
    }
}

func main() {
    // Initialize live cluster with an out-of-sync database proxy and a manual override
    cluster := &MockK8sCluster{
        LiveState: map[string]*Resource{
            "web-server":      {Name: "web-server", Replicas: 3, Image: "nginx:1.25"},
            "db-proxy":        {Name: "db-proxy", Replicas: 1, Image: "envoy:1.25"}, // drift replicas & image
            "rogue-container": {Name: "rogue-container", Replicas: 1, Image: "malicious:latest"}, // manual override
        },
    }

    fmt.Println("Starting Reconciler Loop simulation...")
    Reconcile(cluster)
    fmt.Println("Reconciliation completed. Live cluster matches Git desired state.")
}

package main

import (
    "math/rand"
    "sync"
    "time"
)

type NodeState int

const (
    Follower NodeState = iota
    Candidate
    Leader
)

type VoteRequest struct {
    Term         int
    CandidateID  int
    LastLogIndex int
    LastLogTerm  int
}

type VoteResponse struct {
    Term        int
    VoteGranted bool
}

type Heartbeat struct {
    Term     int
    LeaderID int
}

type RaftNode struct {
    mu        sync.Mutex
    id        int
    state     NodeState
    currentTerm int
    votedFor  int
    peers     []int
    votesRecv int

    electionTimeout time.Duration
    electionTimer   *time.Timer
    heartbeatTicker *time.Ticker

    stateChanged chan struct{}
}

func NewRaftNode(id int, peers []int) *RaftNode {
    n := &RaftNode{
        id:           id,
        state:        Follower,
        currentTerm:  0,
        votedFor:     -1,
        peers:        peers,
        stateChanged: make(chan struct{}, 10),
    }
    n.resetElectionTimeout()
    go n.run()
    return n
}

func (n *RaftNode) resetElectionTimeout() {
    rand.Seed(time.Now().UnixNano() + int64(n.id))
    timeout := time.Duration(150+rand.Intn(150)) * time.Millisecond
    n.electionTimeout = timeout
    if n.electionTimer != nil {
        n.electionTimer.Stop()
    }
    n.electionTimer = time.NewTimer(timeout)
}

func (n *RaftNode) run() {
    for {
        n.mu.Lock()
        state := n.state
        n.mu.Unlock()

        switch state {
        case Follower:
            select {
            case <-n.electionTimer.C:
                n.mu.Lock()
                n.transitionToCandidate()
                n.mu.Unlock()
            case <-n.stateChanged:
            }
        case Candidate:
            select {
            case <-n.electionTimer.C:
                n.mu.Lock()
                n.startElection()
                n.mu.Unlock()
            case <-n.stateChanged:
            }
        case Leader:
            select {
            case <-n.heartbeatTicker.C:
                n.sendHeartbeats()
            case <-n.stateChanged:
            }
        }
    }
}

func (n *RaftNode) transitionToCandidate() {
    n.state = Candidate
    n.startElection()
}

func (n *RaftNode) startElection() {
    n.currentTerm++
    n.votedFor = n.id
    n.votesRecv = 1
    n.resetElectionTimeout()

    term := n.currentTerm
    id := n.id

    for _, peer := range n.peers {
        go func(peerID int) {
            req := VoteRequest{
                Term:        term,
                CandidateID: id,
            }
            res := n.sendRequestVote(peerID, req)
            if res.VoteGranted {
                n.mu.Lock()
                defer n.mu.Unlock()
                if n.state == Candidate && n.currentTerm == term {
                    n.votesRecv++
                    if n.votesRecv > (len(n.peers)+1)/2 {
                        n.transitionToLeader()
                    }
                }
            } else if res.Term > term {
                n.mu.Lock()
                defer n.mu.Unlock()
                n.currentTerm = res.Term
                n.transitionToFollower()
            }
        }(peer)
    }
}

func (n *RaftNode) transitionToLeader() {
    n.state = Leader
    if n.electionTimer != nil {
        n.electionTimer.Stop()
    }
    n.heartbeatTicker = time.NewTicker(50 * time.Millisecond)
    n.stateChanged <- struct{}{}
}

func (n *RaftNode) transitionToFollower() {
    n.state = Follower
    n.votedFor = -1
    if n.heartbeatTicker != nil {
        n.heartbeatTicker.Stop()
    }
    n.resetElectionTimeout()
    n.stateChanged <- struct{}{}
}

func (n *RaftNode) HandleHeartbeat(hb Heartbeat) {
    n.mu.Lock()
    defer n.mu.Unlock()

    if hb.Term >= n.currentTerm {
        n.currentTerm = hb.Term
        if n.state != Follower {
            n.transitionToFollower()
        } else {
            n.resetElectionTimeout()
        }
    }
}

func (n *RaftNode) sendRequestVote(peerID int, req VoteRequest) VoteResponse {
    return VoteResponse{Term: n.currentTerm, VoteGranted: true}
}

func (n *RaftNode) sendHeartbeats() {}

package main

import (
    "context"
    "errors"
    "fmt"
    "sync"
    "sync/atomic"
    "time"
)

// MockLockStore simulates etcd or a similar consensus database
type MockLockStore struct {
    mu          sync.Mutex
    holder      string
    tokenSeq    int64
    expireTime  time.Time
}

type LockResult struct {
    Success      bool
    FencingToken int64
    LeaseID      string
}

var store = &MockLockStore{}

func AcquireLock(ctx context.Context, clientID string, ttl time.Duration) (LockResult, error) {
    store.mu.Lock()
    defer store.mu.Unlock()

    now := time.Now()
    if store.holder != "" && now.Before(store.expireTime) {
        return LockResult{Success: false}, nil
    }

    // Generate a new monotonic fencing token
    atomic.AddInt64(&store.tokenSeq, 1)
    newToken := atomic.LoadInt64(&store.tokenSeq)

    store.holder = clientID
    store.expireTime = now.Add(ttl)

    return LockResult{
        Success:      true,
        FencingToken: newToken,
        LeaseID:      clientID,
    }, nil
}

func RenewLease(ctx context.Context, clientID string, ttl time.Duration) error {
    store.mu.Lock()
    defer store.mu.Unlock()

    if store.holder != clientID {
        return errors.New("lock ownership lost")
    }
    if time.Now().After(store.expireTime) {
        return errors.New("lock lease already expired")
    }

    store.expireTime = time.Now().Add(ttl)
    return nil
}

// MockStorageService implements optimistic lock checking using fencing tokens
type MockStorageService struct {
    mu            sync.Mutex
    highestToken  int64
    resourceValue string
}

var storage = &MockStorageService{highestToken: 0, resourceValue: "initial"}

func (s *MockStorageService) Write(token int64, value string) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    // If incoming token is older than the highest token we have seen, reject the write
    if token < s.highestToken {
        return fmt.Errorf("write rejected: stale token %d is older than current highest token %d", token, s.highestToken)
    }

    s.highestToken = token
    s.resourceValue = value
    return nil
}

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    clientID := "client-node-1"
    ttl := 3 * time.Second

    // 1. Acquire distributed lock
    lockRes, err := AcquireLock(ctx, clientID, ttl)
    if err != nil || !lockRes.Success {
        fmt.Println("Failed to acquire lock")
        return
    }
    fmt.Printf("Lock acquired. Fencing Token: %d\n", lockRes.FencingToken)

    // 2. Spawn background lease-renewal ticker
    var wg sync.WaitGroup
    wg.Add(1)
    go func() {
        defer wg.Done()
        ticker := time.NewTicker(1 * time.Second)
        defer ticker.Stop()

        for {
            select {
            case <-ticker.C:
                err := RenewLease(ctx, clientID, ttl)
                if err != nil {
                    fmt.Printf("Lease renewal failed: %v\n", err)
                    cancel() // Stop execution if lock is lost
                    return
                }
                fmt.Println("Lease renewed successfully")
            case <-ctx.Done():
                return
            }
        }
    }()

    // Simulate work
    time.Sleep(1500 * time.Millisecond)

    // 3. Write to storage with the fencing token
    err = storage.Write(lockRes.FencingToken, "new-data-from-node-1")
    if err != nil {
        fmt.Printf("Error writing to storage: %v\n", err)
    } else {
        fmt.Println("Successfully wrote to storage!")
    }

    cancel()
    wg.Wait()
}

