import (
    "bytes"
    "encoding/binary"
    "fmt"
    "net"
    "time"
)

/* DNSHeader represents the standard 12-byte header of a DNS request/response */
type DNSHeader struct {
    ID      uint16 /* Transaction Identifier */
    Flags   uint16 /* Query flags (e.g., Recursion Desired) */
    QDCount uint16 /* Number of questions */
    ANCount uint16 /* Number of answers */
    NSCount uint16 /* Number of authority records */
    ARCount uint16 /* Number of additional records */
}

func main() {
    /* 1. Resolve target DNS server address (Google Public DNS) */
    resolverAddr, err := net.ResolveUDPAddr("udp", "8.8.8.8:53")
    if err != nil {
        panic(err)
    }

    /* 2. Establish connection using raw UDP socket */
    conn, err := net.DialUDP("udp", nil, resolverAddr)
    if err != nil {
        panic(err)
    }
    defer conn.Close()

    /* 3. Construct the DNS query header */
    header := DNSHeader{
        ID:      0x1234, /* Arbitrary transaction identifier */
        Flags:   0x0100, /* 0x0100 sets the Recursion Desired (RD) bit */
        QDCount: 1,      /* Query contains exactly one question */
    }

    buf := new(bytes.Buffer)
    if err := binary.Write(buf, binary.BigEndian, header); err != nil {
        panic(err)
    }

    /* 4. Encode domain label format: "google.com" -> "\x06google\x03com\x00" */
    domain := "google.com"
    for _, label := range bytes.Split([]byte(domain), []byte(".")) {
        buf.WriteByte(byte(len(label)))
        buf.Write(label)
    }
    buf.WriteByte(0x00) /* Null byte terminating the domain name field */

    /* 5. Set Record Type to A (0x0001) and Class to IN (0x0001) */
    binary.Write(buf, binary.BigEndian, uint16(1)) /* Type A (IPv4 Address) */
    binary.Write(buf, binary.BigEndian, uint16(1)) /* Class IN (Internet) */

    conn.SetDeadline(time.Now().Add(5 * time.Second))

    /* 6. Write raw byte array directly to target resolver port 53 */
    _, err = conn.Write(buf.Bytes())
    if err != nil {
        panic(err)
    }

    /* 7. Receive response packet */
    response := make([]byte, 512)
    n, err := conn.Read(response)
    if err != nil {
        panic(err)
    }

    fmt.Printf("Received raw DNS response: %d bytes\n", n)

    /* 8. Skip Header (12 bytes) and Question Section to locate Answers */
    /* Question length: label length markers (2) + domain string length + null terminator (1) + type (2) + class (2) */
    questionLen := 12 + len(domain) + 2 + 1 + 2 + 2

    if n > questionLen {
        /*
         * Read IPv4 bytes from the trailing segment of the A record.
         * Format of A answer: Name (compression pointer), Type (2), Class (2), TTL (4), RData Len (2), IP (4)
         */
        ipBytes := response[n-4 : n]
        ttlBytes := response[n-10 : n-6]
        ttl := binary.BigEndian.Uint32(ttlBytes)
        fmt.Printf("Resolved IP: %d.%d.%d.%d (TTL: %d seconds)\n", ipBytes[0], ipBytes[1], ipBytes[2], ipBytes[3], ttl)
    }
}

from bcc import BPF
import time

# 1. eBPF kernel program written in C
ebpf_kernel_code = """
#include <uapi/linux/ptrace.h>
#include <linux/sched.h>

// Define an eBPF Hash Map to share data between Kernel and User space
// Key: Process ID (u32), Value: Start Timestamp in ns (u64)
BPF_HASH(start_tracker, u32, u64);

// Hook function for sys_enter_execve tracepoint
int trace_execve_enter(void *ctx) {
    u64 ts = bpf_ktime_get_ns();
    u32 pid = bpf_get_current_pid_tgid() >> 32;

    // Record entry timestamp in the eBPF map
    start_tracker.update(&pid, &ts);
    return 0;
}

// Hook function for sys_exit_execve tracepoint
int trace_execve_exit(void *ctx) {
    u64 exit_ts = bpf_ktime_get_ns();
    u32 pid = bpf_get_current_pid_tgid() >> 32;

    // Look up starting timestamp
    u64 *entry_ts = start_tracker.lookup(&pid);
    if (entry_ts != 0) {
        u64 latency = exit_ts - *entry_ts;
        // Print formatted tracing message to the kernel trace pipe
        bpf_trace_printk("Process ID %d execve latency: %lld ns\\n", pid, latency);
        start_tracker.delete(&pid);
    }
    return 0;
}
"""

# 2. Compile and load bytecode via bcc
b = BPF(text=ebpf_kernel_code)

# 3. Attach hooks to sys_enter_execve and sys_exit_execve tracepoints
b.attach_tracepoint(tp="syscalls:sys_enter_execve", fn_name="trace_execve_enter")
b.attach_tracepoint(tp="syscalls:sys_exit_execve", fn_name="trace_execve_exit")

print("Tracing execve system call latency... Press Ctrl+C to stop.")

# 4. Read events from the kernel trace pipe in user space
while True:
    try:
        (task, pid, cpu, flags, ts, msg) = b.trace_fields()
        print(f"[{time.strftime('%H:%M:%S')}] Task: {task.decode()}, PID: {pid}, Message: {msg.decode()}")
    except KeyboardInterrupt:
        print("Detaching probes and exiting...")
        break

package main

import (
	"encoding/json"
	"fmt"
	"sync"
	"time"
)

// Event represents a domain event
type Event struct {
	ID        string
	AggregateID string
	Type      string
	Version   int
	Payload   []byte
	CreatedAt time.Time
}

// Snapshot represents a snapshot of the aggregate state at a given version
type Snapshot struct {
	AggregateID string
	Version     int
	Data        []byte
}

// AccountAggregate represents a bank account state
type AccountAggregate struct {
	ID      string
	Balance int
	Version int
}

// Event Store
type EventStore struct {
	mu        sync.RWMutex
	events    map[string][]Event
	snapshots map[string]Snapshot
}

func NewEventStore() *EventStore {
	return &EventStore{
		events:    make(map[string][]Event),
		snapshots: make(map[string]Snapshot),
	}
}

// AppendEvents appends new events for an aggregate, checking version conflicts
func (es *EventStore) AppendEvents(aggID string, expectedVersion int, newEvents []Event) error {
	es.mu.Lock()
	defer es.mu.Unlock()

	history := es.events[aggID]
	currentVersion := 0
	if len(history) > 0 {
		currentVersion = history[len(history)-1].Version
	}

	if currentVersion != expectedVersion {
		return fmt.Errorf("concurrent modification error: expected version %d, got %d", expectedVersion, currentVersion)
	}

	for _, event := range newEvents {
		es.events[aggID] = append(es.events[aggID], event)
	}
	return nil
}

// SaveSnapshot saves an aggregate snapshot
func (es *EventStore) SaveSnapshot(aggID string, version int, data []byte) {
	es.mu.Lock()
	es.snapshots[aggID] = Snapshot{
		AggregateID: aggID,
		Version:     version,
		Data:        data,
	}
	es.mu.Unlock()
}

// ReadEvents returns events for an aggregate starting after a specific version
func (es *EventStore) GetEventsForAggregate(aggID string, afterVersion int) []Event {
	es.mu.RLock()
	defer es.mu.RUnlock()

	var result []Event
	for _, event := range es.events[aggID] {
		if event.Version > afterVersion {
			result = append(result, event)
		}
	}
	return result
}

// Apply updates the aggregate balance according to the event
func (acc *AccountAggregate) Apply(event Event) {
	switch event.Type {
	case "AccountOpened":
		acc.ID = event.AggregateID
		acc.Balance = 0
	case "MoneyDeposited":
		var amount int
		_ = json.Unmarshal(event.Payload, &amount)
		acc.Balance += amount
	case "MoneyWithdrawn":
		var amount int
		_ = json.Unmarshal(event.Payload, &amount)
		acc.Balance -= amount
	}
	acc.Version = event.Version
}

// ReconstructState recreates aggregate state from snapshot + remaining events
func (es *EventStore) ReconstructState(aggID string) (*AccountAggregate, error) {
	es.mu.RLock()
	snapshot, hasSnapshot := es.snapshots[aggID]
	es.mu.RUnlock()

	acc := &AccountAggregate{}
	startVersion := 0

	if hasSnapshot {
		if err := json.Unmarshal(snapshot.Data, &acc); err != nil {
			return nil, err
		}
		startVersion = snapshot.Version
	}

	events := es.GetEventsForAggregate(aggID, startVersion)
	for _, event := range events {
		acc.Apply(event)
	}

	return acc, nil
}

// CQRS Read Model View Table
type AccountView struct {
	AccountID string
	Balance   int
	LastUpdated time.Time
}

// CQRS Projector updates the read database
type Projector struct {
	mu        sync.RWMutex
	readModel map[string]AccountView
}

func (p *Projector) Project(event Event) {
	p.mu.Lock()
	defer p.mu.Unlock()

	view, exists := p.readModel[event.AggregateID]
	if !exists {
		view = AccountView{AccountID: event.AggregateID}
	}

	switch event.Type {
	case "AccountOpened":
		view.Balance = 0
	case "MoneyDeposited":
		var amount int
		_ = json.Unmarshal(event.Payload, &amount)
		view.Balance += amount
	case "MoneyWithdrawn":
		var amount int
		_ = json.Unmarshal(event.Payload, &amount)
		view.Balance -= amount
	}

	view.LastUpdated = event.CreatedAt
	p.readModel[event.AggregateID] = view
}

func main() {
	store := NewEventStore()
	projector := &Projector{readModel: make(map[string]AccountView)}

	aggID := "acc_1001"

	payload1, _ := json.Marshal(0)
	events := []Event{
		{ID: "e1", AggregateID: aggID, Type: "AccountOpened", Version: 1, Payload: payload1, CreatedAt: time.Now()},
	}
	_ = store.AppendEvents(aggID, 0, events)
	projector.Project(events[0])

	payload2, _ := json.Marshal(500)
	events = []Event{
		{ID: "e2", AggregateID: aggID, Type: "MoneyDeposited", Version: 2, Payload: payload2, CreatedAt: time.Now()},
	}
	_ = store.AppendEvents(aggID, 1, events)
	projector.Project(events[0])

	currentAggregate, _ := store.ReconstructState(aggID)
	snapshotData, _ := json.Marshal(currentAggregate)
	store.SaveSnapshot(aggID, 2, snapshotData)

	payload3, _ := json.Marshal(100)
	events = []Event{
		{ID: "e3", AggregateID: aggID, Type: "MoneyWithdrawn", Version: 3, Payload: payload3, CreatedAt: time.Now()},
	}
	_ = store.AppendEvents(aggID, 2, events)
	projector.Project(events[0])

	reconstructed, _ := store.ReconstructState(aggID)
	fmt.Printf("Reconstructed Balance: $%d (Version: %d)\n", reconstructed.Balance, reconstructed.Version)

	projector.mu.RLock()
	view := projector.readModel[aggID]
	projector.mu.RUnlock()
	fmt.Printf("Read Model View Balance: $%d (Last Updated: %s)\n", view.Balance, view.LastUpdated.Format("15:04:05"))
}

