)

func readConfig(path string) ([]byte, error) {
  f, err := os.Open(path)
  if err != nil {
    return nil, err
  }
  defer f.Close() // fd is freed when the function returns

  buf := make([]byte, 4096)
  n, err := f.Read(buf)
  if err != nil {
    return nil, err
  }
  return buf[:n], nil
}

func main() {
  data, err := readConfig("/etc/hostname")
  if err != nil {
    fmt.Fprintln(os.Stderr, err)
    os.Exit(1)
  }
  fmt.Printf("hostname: %s\n", data)
}

#include <stdio.h>
#include <stdlib.h>

#define STACK_MAX 256
#define INITIAL_GC_THRESHOLD 8

typedef enum {
    OBJ_INT,
    OBJ_PAIR
} ObjectType;

typedef struct sObject {
    ObjectType type;
    unsigned char marked;
    struct sObject* next; /* Linked list of all allocated objects */

    union {
        int value;
        struct {
            struct sObject* head;
            struct sObject* tail;
        };
    };
} Object;

typedef struct {
    Object* stack[STACK_MAX];
    int stackSize;
    Object* firstObject; /* Head of global allocation list */
    int numObjects;
    int maxObjects;      /* GC trigger threshold */
} VM;

/* Allocate and initialize a clean Virtual Machine instance */
VM* newVM() {
    VM* vm = malloc(sizeof(VM));
    vm->stackSize = 0;
    vm->firstObject = NULL;
    vm->numObjects = 0;
    vm->maxObjects = INITIAL_GC_THRESHOLD;
    return vm;
}

void push(VM* vm, Object* value) {
    if (vm->stackSize >= STACK_MAX) {
        fprintf(stderr, "Stack overflow!\n");
        exit(1);
    }
    vm->stack[vm->stackSize++] = value;
}

Object* pop(VM* vm) {
    if (vm->stackSize <= 0) {
        fprintf(stderr, "Stack underflow!\n");
        exit(1);
    }
    return vm->stack[--vm->stackSize];
}

/* Mark phase: recursively flag reachable objects starting from stack roots */
void mark(Object* object) {
    if (object == NULL) return;
    if (object->marked) return; /* Prevent infinite loops on cycles */

    object->marked = 1;

    if (object->type == OBJ_PAIR) {
        mark(object->head);
        mark(object->tail);
    }
}

/* Walk the VM stack to find and mark all active root objects */
void markAll(VM* vm) {
    for (int i = 0; i < vm->stackSize; i++) {
        mark(vm->stack[i]);
    }
}

/* Sweep phase: free unmarked blocks and reset marks for remaining objects */
void sweep(VM* vm) {
    Object** object = &vm->firstObject;
    while (*object) {
        if (!(*object)->marked) {
            /* Object is dead, unlink it from global registry and free memory */
            Object* unreached = *object;
            *object = unreached->next;
            free(unreached);
            vm->numObjects--;
        } else {
            /* Object is alive, clear marked flag for the next GC run */
            (*object)->marked = 0;
            object = &(*object)->next;
        }
    }
}

/* Trigger garbage collection cycle */
void gc(VM* vm) {
    int oldObjCount = vm->numObjects;
    markAll(vm);
    sweep(vm);

    /* Adjust trigger limit dynamically based on surviving count */
    vm->maxObjects = vm->numObjects == 0 ? INITIAL_GC_THRESHOLD : vm->numObjects * 2;
    printf("GC: Collected %d objects, %d remaining in memory.\n", oldObjCount - vm->numObjects, vm->numObjects);
}

/* Allocate new object node, triggering GC automatically if threshold is crossed */
Object* newObject(VM* vm, ObjectType type) {
    if (vm->numObjects >= vm->maxObjects) {
        printf("GC threshold reached. Starting sweep...\n");
        gc(vm);
    }

    Object* object = malloc(sizeof(Object));
    object->type = type;
    object->marked = 0;

    /* Link new node to the head of the VM global allocation tracker */
    object->next = vm->firstObject;
    vm->firstObject = object;

    vm->numObjects++;
    return object;
}

void pushInt(VM* vm, int intValue) {
    Object* obj = newObject(vm, OBJ_INT);
    obj->value = intValue;
    push(vm, obj);
}

Object* pushPair(VM* vm) {
    Object* obj = newObject(vm, OBJ_PAIR);
    obj->tail = pop(vm);
    obj->head = pop(vm);
    push(vm, obj);
    return obj;
}

void freeVM(VM* vm) {
    vm->stackSize = 0;
    gc(vm); /* Reclaims all remaining allocated objects */
    free(vm);
}

int main() {
    printf("Initializing VM...\n");
    VM* vm = newVM();

    printf("Allocating objects...\n");
    for (int i = 0; i < 6; i++) {
        pushInt(vm, i);
    }
    pushPair(vm);
    pushPair(vm);

    /* Pop the root reference to simulate losing reachability to structures */
    pop(vm);

    printf("Allocating more to trigger automatic garbage collection...\n");
    for (int i = 0; i < 10; i++) {
        pushInt(vm, i);
    }

    freeVM(vm);
    return 0;
}

package main

import (
    "fmt"
    "math"
    "math/rand"
    "sync"
    "time"
)

type NodeState struct {
    Addr       string
    Heartbeat  int64
    Generation int64
    LastSeen   time.Time
}

type GossipNode struct {
    mu          sync.Mutex
    addr        string
    membership  map[string]*NodeState
    intervals   map[string][]float64 // stores heartbeat intervals in ms
    maxSamples  int
}

func NewGossipNode(addr string) *GossipNode {
    return &GossipNode{
        addr:       addr,
        membership: make(map[string]*NodeState),
        intervals:  make(map[string][]float64),
        maxSamples: 10,
    }
}

// RecordHeartbeat logs a heartbeat interval to calculate the phi value
func (gn *GossipNode) RecordHeartbeat(nodeAddr string) {
    gn.mu.Lock()
    defer gn.mu.Unlock()

    state, exists := gn.membership[nodeAddr]
    now := time.Now()
    if exists {
        diff := float64(now.Sub(state.LastSeen).Milliseconds())
        gn.intervals[nodeAddr] = append(gn.intervals[nodeAddr], diff)
        if len(gn.intervals[nodeAddr]) > gn.maxSamples {
            gn.intervals[nodeAddr] = gn.intervals[nodeAddr][1:]
        }
        state.Heartbeat++
        state.LastSeen = now
    } else {
        gn.membership[nodeAddr] = &NodeState{
            Addr:       nodeAddr,
            Heartbeat:  1,
            Generation: 1,
            LastSeen:   now,
        }
    }
}

// CalculatePhi estimates the suspicion score using exponential distribution
func (gn *GossipNode) CalculatePhi(nodeAddr string, now time.Time) float64 {
    gn.mu.Lock()
    defer gn.mu.Unlock()

    state, exists := gn.membership[nodeAddr]
    if !exists {
        return 10.0 // Node unseen is highly suspicious
    }

    history := gn.intervals[nodeAddr]
    if len(history) < 3 {
        return 0.0 // Not enough statistics yet
    }

    var sum float64
    for _, val := range history {
        sum += val
    }
    meanInterval := sum / float64(len(history))
    elapsed := float64(now.Sub(state.LastSeen).Milliseconds())

    // Probability P_later(t) = e^(-t / mean)
    // phi = -log10(P_later(t))
    pLater := math.Exp(-elapsed / meanInterval)
    if pLater <= 0 {
        return 12.0 // Cap at safe maximum
    }
    phi := -math.Log10(pLater)
    return phi
}

// MergeState processes incoming state updates from a remote peer
func (gn *GossipNode) MergeState(incoming map[string]*NodeState) {
    gn.mu.Lock()
    defer gn.mu.Unlock()

    for addr, remoteState := range incoming {
        localState, exists := gn.membership[addr]
        if !exists || remoteState.Generation > localState.Generation ||
            (remoteState.Generation == localState.Generation && remoteState.Heartbeat > localState.Heartbeat) {
            gn.membership[addr] = &NodeState{
                Addr:       remoteState.Addr,
                Heartbeat:  remoteState.Heartbeat,
                Generation: remoteState.Generation,
                LastSeen:   time.Now(),
            }
            fmt.Printf("[%s] Updated member %s to HB %d, Gen %d\n", gn.addr, addr, remoteState.Heartbeat, remoteState.Generation)
        }
    }
}

func (gn *GossipNode) SelectRandomPeer(exclude string) string {
    gn.mu.Lock()
    defer gn.mu.Unlock()

    var peers []string
    for addr := range gn.membership {
        if addr != gn.addr && addr != exclude {
            peers = append(peers, addr)
        }
    }
    if len(peers) == 0 {
        return ""
    }
    return peers[rand.Intn(len(peers))]
}

func main() {
    // Instantiate a localized node cluster
    nodeA := NewGossipNode("10.0.0.1:8000")
    nodeB := NewGossipNode("10.0.0.2:8000")

    // Bootstrap cluster
    nodeA.membership[nodeB.addr] = &NodeState{Addr: nodeB.addr, Heartbeat: 1, Generation: 1, LastSeen: time.Now()}
    nodeB.membership[nodeA.addr] = &NodeState{Addr: nodeA.addr, Heartbeat: 1, Generation: 1, LastSeen: time.Now()}

    // Record heartbeat history for statistical stability
    for i := 0; i < 5; i++ {
        nodeA.RecordHeartbeat(nodeB.addr)
        time.Sleep(100 * time.Millisecond)
    }

    // Simulate Normal Run
    now := time.Now()
    phi := nodeA.CalculatePhi(nodeB.addr, now)
    fmt.Printf("Initial Phi check for Node B: %f (Normal values < 1.0)\n", phi)

    // Simulate network delay / disconnect
    staleTime := now.Add(800 * time.Millisecond)
    phiStale := nodeA.CalculatePhi(nodeB.addr, staleTime)
    fmt.Printf("Delayed Phi check for Node B after 800ms: %f (Highly suspicious, should trigger alerts)\n", phiStale)
}

