package main

import (
    "fmt"
    "os"
    "os/exec"
    "syscall"
)

// Run this code on a Linux host (or in a VM).
// Execute with: go run main.go run <command> <args>
func main() {
    if len(os.Args) < 2 {
        fmt.Println("Usage: go run main.go run [command] [args...]")
        os.Exit(1)
    }

    switch os.Args[1] {
    case "run":
        runParent()
    case "child":
        runChild()
    default:
        fmt.Printf("Unknown command: %s\n", os.Args[1])
        os.Exit(1)
    }
}

func runParent() {
    fmt.Printf("Running parent process (PID: %d)\n", os.Getpid())

    // Re-execute this binary as a child process, specifying the "child" argument
    cmd := exec.Command("/proc/self/exe", append([]string{"child"}, os.Args[2:]...)...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    // Configure namespace isolation flags
    cmd.SysProcAttr = &syscall.SysProcAttr{
        Cloneflags: syscall.CLONE_NEWUTS | // New hostnames namespace
            syscall.CLONE_NEWPID | // New process ID space (child will be PID 1)
            syscall.CLONE_NEWNS |  // New mount namespace
            syscall.CLONE_NEWNET,  // New isolated loopback network
    }

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error running child process: %v\n", err)
        os.Exit(1)
    }
}

func runChild() {
    fmt.Printf("Running child container sandbox (PID: %d)\n", os.Getpid())

    // 1. Set hostname inside the isolated UTS namespace
    if err := syscall.Sethostname([]byte("container-sandbox")); err != nil {
        fmt.Printf("Failed to set hostname: %v\n", err)
    }

    // 2. Isolate the mount namespace: mount a private /proc filesystem
    // This ensures commands like `ps` only see processes in this container
    if err := syscall.Mount("proc", "/proc", "proc", 0, ""); err != nil {
        fmt.Printf("Failed to mount /proc: %v\n", err)
    }

    // 3. Execute the target program (e.g. /bin/sh)
    userCmd := os.Args[2]
    userArgs := os.Args[3:]

    cmd := exec.Command(userCmd, userArgs...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error executing user command: %v\n", err)
    }

    // Unmount proc before exiting to clean up
    syscall.Unmount("/proc", 0)
}

package main

import (
    "context"
    "log"
    "net/http"
    "net/http/httputil"
    "net/url"
    "sync"
    "sync/atomic"
    "time"
)

type Backend struct {
    URL          *url.URL
    Alive        bool
    mux          sync.RWMutex
    ReverseProxy *httputil.ReverseProxy
}

func (b *Backend) SetAlive(alive bool) {
    b.mux.Lock()
    b.Alive = alive
    b.mux.Unlock()
}

func (b *Backend) IsAlive() bool {
    b.mux.RLock()
    defer b.mux.RUnlock()
    return b.Alive
}

type ServerPool struct {
    backends []*Backend
    current  uint64
}

func (s *ServerPool) AddBackend(backend *Backend) {
    s.backends = append(s.backends, backend)
}

func (s *ServerPool) NextIndex() int {
    return int(atomic.AddUint64(&s.current, 1) % uint64(len(s.backends)))
}

func (s *ServerPool) GetNextPeer() *Backend {
    n := len(s.backends)
    for i := 0; i < n; i++ {
        idx := s.NextIndex()
        if s.backends[idx].IsAlive() {
            return s.backends[idx]
        }
    }
    return nil
}

func (s *ServerPool) HealthCheck() {
    for _, b := range s.backends {
        status := b.isAlive()
        b.SetAlive(status)
        if !status {
            log.Printf("Backend %s is DOWN", b.URL.String())
        }
    }
}

func (b *Backend) isAlive() bool {
    client := http.Client{
        Timeout: 2 * time.Second,
    }
    resp, err := client.Get(b.URL.String() + "/health")
    if err != nil {
        return false
    }
    defer resp.Body.Close()
    return resp.StatusCode == http.StatusOK
}

func main() {
    serverPool := &ServerPool{}

    targets := []string{
        "http://localhost:8081",
        "http://localhost:8082",
        "http://localhost:8083",
    }

    for _, target := range targets {
        targetURL, _ := url.Parse(target)
        proxy := httputil.NewSingleHostReverseProxy(targetURL)

        backend := &Backend{
            URL:          targetURL,
            Alive:        true,
            ReverseProxy: proxy,
        }
        serverPool.AddBackend(backend)
    }

    go func() {
        ticker := time.NewTicker(10 * time.Second)
        for range ticker.C {
            serverPool.HealthCheck()
        }
    }()

    frontendHandler := func(w http.ResponseWriter, r *http.Request) {
        peer := serverPool.GetNextPeer()
        if peer != nil {
            peer.ReverseProxy.ServeHTTP(w, r)
            return
        }
        http.Error(w, "Service Unavailable", http.StatusServiceUnavailable)
    }

    server := http.Server{
        Addr:    ":8080",
        Handler: http.HandlerFunc(frontendHandler),
    }

    log.Fatal(server.ListenAndServe())
}

package main

import (
    "fmt"
    "io"
    "net"
    "os"
    "syscall"
)

// ZeroCopyStreamer demonstrates streaming file segments directly to a TCP socket
// using the sendfile system call, bypassing user-space memory buffers.
type ZeroCopyStreamer struct {
    logFile *os.File
}

func NewZeroCopyStreamer(path string) (*ZeroCopyStreamer, error) {
    file, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    return &ZeroCopyStreamer{logFile: file}, nil
}

// StreamSegment reads a chunk of the commit log from offset and writes it directly to conn
func (zs *ZeroCopyStreamer) StreamSegment(conn net.Conn, offset int64, length int64) (int64, error) {
    // In standard Go, if conn is a TCP connection and zs.logFile is a local file,
    // io.Copy or conn.ReadFrom will automatically optimize down to the sendfile system call
    // on Linux and Darwin.
    // To explicitly show system call mechanics, we can extract the raw file descriptors:

    tcpConn, ok := conn.(*net.TCPConn)
    if !ok {
        // Fallback to standard user-space copy if not a TCP connection
        fmt.Println("Fallback: copying via user space")
        _, err := zs.logFile.Seek(offset, io.SeekStart)
        if err != nil {
            return 0, err
        }
        return io.CopyN(conn, zs.logFile, length)
    }

    connVal, err := tcpConn.File()
    if err != nil {
        return 0, err
    }
    defer connVal.Close()

    dstFd := int(connVal.Fd())
    srcFd := int(zs.logFile.Fd())

    // Trigger Syscall sendfile(dstFd, srcFd, offset, length)
    // On macOS/Darwin, the system call is different (uses transfer flags), but Linux sendfile
    // is standard for system-level networking. Below we use the syscall package.
    // Note: syscall.Sendfile is OS-specific; on macOS, we simulate/wrap or use standard io.Copy
    // which compiles cross-platform.

    var written int
    off := offset

    // Using a cross-platform compilation safety fallback
    written, err = syscall.Sendfile(dstFd, srcFd, &off, int(length))
    if err != nil {
        return 0, err
    }

    return int64(written), nil
}

func main() {
    // Minimal execution demonstration
    fmt.Println("Zero-copy commit log reader configured.")
}

