int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <filename> <search_string>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *filename = argv[1];
    const char *search_str = argv[2];
    size_t search_len = strlen(search_str);

    int fd = open(filename, O_RDONLY);
    if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }

    struct stat sb;
    if (fstat(fd, &sb) == -1) { perror("fstat"); close(fd); exit(EXIT_FAILURE); }
    size_t file_size = sb.st_size;

    if (file_size == 0) {
        printf("File is empty.\n");
        close(fd);
        return 0;
    }

    // Map the file into the process's virtual memory address space
    char *mapped_data = mmap(NULL, file_size, PROT_READ, MAP_SHARED, fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap"); close(fd); exit(EXIT_FAILURE);
    }

    // Declare advice to guide the kernel's read-ahead paging engine
    madvise(mapped_data, file_size, MADV_SEQUENTIAL);
    madvise(mapped_data, file_size, MADV_WILLNEED);

    // Perform in-memory search across mapped data pointer offsets
    size_t match_count = 0;
    for (size_t i = 0; i <= file_size - search_len; i++) {
        if (memcmp(&mapped_data[i], search_str, search_len) == 0) {
            match_count++;
            printf("Match found at offset %zu\n", i);
        }
    }

    printf("Total matches: %zu\n", match_count);

    // Clean up resources
    if (munmap(mapped_data, file_size) == -1) { perror("munmap"); }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/epoll.h>

#define MAX_EVENTS 64
#define PORT 8080
#define BUFFER_SIZE 1024

/* Set socket descriptor to non-blocking mode */
int make_socket_non_blocking(int sfd) {
    int flags = fcntl(sfd, F_GETFL, 0);
    if (flags == -1) {
        perror("fcntl F_GETFL");
        return -1;
    }
    flags |= O_NONBLOCK;
    if (fcntl(sfd, F_SETFL, flags) == -1) {
        perror("fcntl F_SETFL");
        return -1;
    }
    return 0;
}

int main() {
    int listen_fd, epoll_fd;
    struct sockaddr_in address;
    int opt = 1;

    /* 1. Create a raw TCP socket */
    listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    /* 2. Enable SO_REUSEADDR socket option to reuse port immediately */
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt SO_REUSEADDR failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    /* 3. Bind socket to target address and port */
    if (bind(listen_fd, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("bind failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Configure socket as non-blocking */
    if (make_socket_non_blocking(listen_fd) == -1) {
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 5. Listen for incoming connections (SYN backlog capacity: 128) */
    if (listen(listen_fd, 128) == -1) {
        perror("listen failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 6. Initialize epoll instance */
    epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1 failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event event;
    struct epoll_event events[MAX_EVENTS];

    event.data.fd = listen_fd;
    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitor */

    /* 7. Register listen socket with epoll */
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, listen_fd, &event) == -1) {
        perror("epoll_ctl add listen_fd failed");
        close(listen_fd);
        close(epoll_fd);
        exit(EXIT_FAILURE);
    }

    /* 8. Execute high-performance event loop */
    while (1) {
        int n = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            if ((events[i].events & EPOLLERR) ||
                (events[i].events & EPOLLHUP) ||
                (!(events[i].events & EPOLLIN))) {
                /* Handle error or socket disconnection */
                fprintf(stderr, "epoll error on fd %d\n", events[i].data.fd);
                close(events[i].data.fd);
                continue;
            }

            if (listen_fd == events[i].data.fd) {
                /* Handle new incoming connection requests */
                while (1) {
                    struct sockaddr in_addr;
                    socklen_t in_len = sizeof(in_addr);
                    int infd = accept(listen_fd, &in_addr, &in_len);
                    if (infd == -1) {
                        if ((errno == EAGAIN) || (errno == EWOULDBLOCK)) {
                            /* All connections in backlog accepted */
                            break;
                        }
                        perror("accept failed");
                        break;
                    }

                    if (make_socket_non_blocking(infd) == -1) {
                        close(infd);
                        continue;
                    }

                    event.data.fd = infd;
                    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitoring */
                    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, infd, &event) == -1) {
                        perror("epoll_ctl add client fd failed");
                        close(infd);
                    }
                }
            } else {
                /* Process data ready to read on existing connection */
                int client_fd = events[i].data.fd;
                char buf[BUFFER_SIZE];
                int close_conn = 0;

                while (1) {
                    ssize_t count = read(client_fd, buf, sizeof(buf));
                    if (count == -1) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            perror("read error");
                            close_conn = 1;
                        }
                        break;
                    } else if (count == 0) {
                        /* EOF, client closed connection */
                        close_conn = 1;
                        break;
                    }

                    /* Echo the read bytes back to the client socket */
                    ssize_t written = write(client_fd, buf, count);
                    if (written == -1) {
                        perror("write error");
                        close_conn = 1;
                        break;
                    }
                }

                if (close_conn) {
                    close(client_fd);
                }
            }
        }
    }
    close(listen_fd);
    close(epoll_fd);
    return 0;
}

package main

import (
    "context"
    "net/http"
    "time"

    "github.com/prometheus/client_golang/prometheus"
    "github.com/prometheus/client_golang/prometheus/promauto"
    "go.opentelemetry.io/otel"
    "go.opentelemetry.io/otel/attribute"
    "go.opentelemetry.io/otel/propagation"
    "go.opentelemetry.io/otel/trace"
)

var (
    httpRequestsTotal = promauto.NewCounterVec(
        prometheus.CounterOpts{
            Name: "http_requests_total",
            Help: "Total number of HTTP requests processed.",
        },
        []string{"path", "status"},
    )
    httpRequestDuration = promauto.NewHistogramVec(
        prometheus.HistogramOpts{
            Name:    "http_request_duration_seconds",
            Help:    "Latency of HTTP requests in seconds.",
            Buckets: prometheus.DefBuckets,
        },
        []string{"path"},
    )
)

func traceMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()

        // 1. Extract W3C traceparent header context from incoming call
        propagator := propagation.TraceContext{}
        ctx := propagator.Extract(r.Context(), propagation.HeaderCarrier(r.Header))

        // 2. Start a new span linked to the parent trace context
        tracer := otel.Tracer("http-server")
        ctx, span := tracer.Start(ctx, "ServeHTTP", trace.WithSpanKind(trace.SpanKindServer))
        defer span.End()

        span.SetAttributes(
            attribute.String("http.method", r.Method),
            attribute.String("http.path", r.URL.Path),
        )

        wrapped := &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}
        next.ServeHTTP(wrapped, r.WithContext(ctx))

        // 3. Record metrics (latency histogram and request counters)
        duration := time.Since(start).Seconds()
        httpRequestDuration.WithLabelValues(r.URL.Path).Observe(duration)
        httpRequestsTotal.WithLabelValues(r.URL.Path, http.StatusText(wrapped.statusCode)).Inc()

        span.SetAttributes(attribute.Int("http.status_code", wrapped.statusCode))
    })
}

func callDownstreamService(ctx context.Context, url string) error {
    // 4. Inject active trace context into outgoing HTTP request
    req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
    if err != nil {
        return err
    }

    propagator := propagation.TraceContext{}
    propagator.Inject(ctx, propagation.HeaderCarrier(req.Header))

    client := &http.Client{Timeout: 5 * time.Second}
    resp, err := client.Do(req)
    if err != nil {
        return err
    }
    defer resp.Body.Close()

    return nil
}

type responseWriter struct {
    http.ResponseWriter
    statusCode int
}

func (rw *responseWriter) WriteHeader(code int) {
    rw.statusCode = code
    rw.ResponseWriter.WriteHeader(code)
}

